interface StationView { val query: String; fun showTotal(total: Double) }
class StationPresenter(
    private val view: StationView,
    private val model: StationModel,
) {
    fun queryChanged() = view.showTotal(model.total(view.query))
}
class StationActivity : AppCompatActivity(), StationView {   // passive view
    override val query get() = queryInput.text.toString()
    override fun showTotal(total: Double) { totalLabel.text = "%.2f".format(total) }
}

class StationState {
    var total by Delegates.observable(0.0) { _, _, new ->
        totalLabel.text = "%.2f".format(new)
    }
}
class StationPresenter(private val state: StationState, private val model: StationModel) {
    val queryChanged: (String) -> Unit = { q -> state.total = model.total(q) }
}
